package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import java.math.*;import java.time.*;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;
/** Current-authorized billing qualification from previously verified original-object registration.
 * This metadata reader does not claim a new download/read receipt for private provider bytes. */
public final class FormalInvocationCompleted {
 private final JdbcTemplate db;private final FormalVerificationJobs jobs;private final FormalInvocationCurrent current;private final FormalInvocationSettlement settlement;private final FormalInvocationObjectRegistration objects;private final FormalProviderCaptureEvidence captures;private final FormalInvocationSchema schema;private final ResourceReadAuthority resources;private final SchemaCatalogue published;
 public FormalInvocationCompleted(DataSource data,FormalVerificationJobs jobs,FormalInvocationCurrent current,FormalInvocationSettlement settlement,FormalInvocationObjectRegistration objects,FormalProviderCaptureEvidence captures,FormalInvocationSchema schema,ResourceReadAuthority resources)throws Exception{db=new JdbcTemplate(data);db.setQueryTimeout(5);this.jobs=jobs;this.current=current;this.settlement=settlement;this.objects=objects;this.captures=captures;this.schema=schema;this.resources=resources;published=SchemaCatalogue.fromClasspath();}
 public final class SettledProof {
  private final EnterpriseAccess.Admission admission;private final JsonNode receipt;private final CommonProtocol.ArtifactRef artifact;private final FormalVerificationJobs.Job job;private final FormalInvocationCurrent.Verified authority;
  private SettledProof(EnterpriseAccess.Admission a,FormalVerificationJobs.Job job,JsonNode receipt,CommonProtocol.ArtifactRef artifact,FormalInvocationCurrent.Verified authority){admission=a;this.job=job;this.receipt=receipt.deepCopy();this.artifact=artifact;this.authority=authority;}
  public String verificationId(){return job.verification();}public String invocationId(){return text(receipt,"invocation_id");}public String runId(){return job.run();}public String stepId(){return job.step();}public String actionId(){return job.action();}public String requestBodySha256(){return job.requestHash();}public String inputSha256(){return job.inputHash();}public String modelRevision(){return job.model();}public String credentialReferenceId(){return authority.credentialReferenceId();}public String credentialRevision(){return authority.credentialRevision();}
  public CommonProtocol.ArtifactRef receiptArtifact(){return artifact;}public String receiptSha256(){return artifact.sha256();}public String priceVersion(){return text(receipt,"price_version");}public String currency(){return text(receipt,"currency");}public BigDecimal settledAmount(){return new BigDecimal(text(receipt,"known_amount"));}public String usageReceiptId(){return text(receipt,"usage_receipt_id");}public Instant verifiedAt(){return Instant.parse(text(receipt,"verified_at"));}public Instant settledAt(){return Instant.parse(text(receipt,"settled_at"));}
  public void requireCurrent()throws Exception{var fresh=require(admission,invocationId(),verificationId());if(!schema.canonical(receipt).equals(schema.canonical(fresh.receipt)))bad();}
 }
 SettledProof require(EnterpriseAccess.Admission a,String invocation,String verification)throws Exception{
  WireValues.uuid(invocation);WireValues.uuid(verification);String tenant=a.context().tenant_id();if(!TenantScope.requireCurrent().tenantId().equals(tenant)||!TenantScope.requireCurrent().subjectId().equals(a.actorId()))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);
  var job=jobs.read(tenant,verification).orElseThrow(()->new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE));var authorized=current.require(a,job,false);
  var record=settlement.read(tenant,invocation).orElseThrow(()->new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE));var r=record.receipt();if(!record.settled()||!"SUCCEEDED".equals(text(r,"status"))||!verification.equals(text(r,"verification_id")))throw new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE);
  var result=objects.registered(tenant,invocation,"MODEL_RESULT").orElseThrow(()->new TenantAccessException(ErrorCode.CONTENT_MISMATCH));var capture=objects.registered(tenant,invocation,"PROVIDER_CAPTURE").orElseThrow(()->new TenantAccessException(ErrorCode.CONTENT_MISMATCH));
  for(var artifact:List.of(result.artifact(),capture.artifact()))resources.require(a,new PermissionProtocol.Scope(tenant,job.project(),"ARTIFACT",artifact.artifactId()),"artifact.read","MODEL_VERIFICATION");
  var binding=schema.parse(one(db.query("SELECT JSON_OBJECT('actual_send_manifest',i.actual_send_manifest,'actual_send_sha256',i.actual_send_sha256,'input_sha256',i.input_sha256,'attempt_id',a.attempt_id,'request_sha256',a.request_sha256,'service_uri',a.service_uri,'certificate_sha256',a.certificate_sha256,'trust_revision',a.trust_revision,'lease_generation',CAST(a.lease_generation AS CHAR),'project_id',i.project_id,'created_by',i.created_by,'classification',i.classification) FROM invocation i JOIN formal_invocation_attempt a ON a.tenant_id=i.tenant_id AND a.invocation_id=i.invocation_id WHERE i.tenant_id=? AND i.invocation_id=? AND i.run_id=? AND i.step_id=? AND i.action_id=? AND i.verification_id=? AND i.created_by=? AND i.dispatch_generation=1 AND a.dispatch_generation=1 AND a.lease_generation=i.lease_generation AND a.created_by=i.created_by AND a.input_sha256=i.input_sha256 AND a.schema_version='1.0.0' AND a.schema_manifest_sha256=? LIMIT 2",(rs,n)->rs.getString(1),tenant,invocation,job.run(),job.step(),job.action(),verification,job.actor(),schema.manifestSha256())));
  FormalInvocationDispatch.verifyEvidence(db,schema,tenant,invocation,binding);
  byte[] resultBytes=ContentReadAuthorization.canonicalBytes(result.canonicalPayload());var normalized=published.bindPublished(published.schemaRef("model-stream","ModelResult"),published.schemaDigest("model-stream"),resultBytes);if(!result.artifact().sha256().equals(WireValues.sha256(resultBytes))||!result.artifact().schemaRef().equals(published.schemaRef("model-stream","ModelResult")))bad();var resultNode=schema.parse(normalized.canonicalJson());
  if(!invocation.equals(text(resultNode,"invocation_id"))||!job.context().equals(text(resultNode,"context_manifest_id"))||!job.model().equals(text(resultNode,"model_config_revision")))bad();
  byte[] captureBytes=ContentReadAuthorization.canonicalBytes(capture.canonicalPayload());if(!capture.artifact().sha256().equals(WireValues.sha256(captureBytes))||!capture.artifact().schemaRef().equals(FormalProviderCaptureSchema.REF))bad();var evidence=captures.inspect(invocation,text(r,"attempt_id"),binding,resultNode,captureBytes);var determined=FormalInvocationAccounting.determine(authorized.price(),evidence.usage(),evidence.calls(),evidence.terminal());
  if(!determined.maySettleAll()||determined.amount().orElseThrow().compareTo(new BigDecimal(text(r,"known_amount")))!=0||!determined.tokens().orElseThrow().toString().equals(text(r,"known_tokens"))||!determined.calls().orElseThrow().toString().equals(text(r,"known_calls"))||!text(evidence.artifact().required("metadata"),"receipt_id").equals(text(r,"usage_receipt_id"))||!authorized.price().priceVersion().equals(text(r,"price_version"))||!authorized.price().currency().equals(text(r,"currency")))bad();
  authorized.requireCurrent();result.requireUnchanged();capture.requireUnchanged();return new SettledProof(a,job,r,result.artifact(),authorized);
 }
 private static String text(JsonNode n,String k){var v=n.required(k);if(!v.isTextual())bad();return v.textValue();}private static <T>T one(List<T> r){if(r.size()!=1||r.get(0)==null)bad();return r.get(0);}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
